<script setup>
import { onBeforeUnmount,onMounted,ref } from 'vue'
const clientes=ref([]),mensaje=ref(''),error=ref(false),cargando=ref(true),fotoUrls=ref({})
onMounted(async()=>{try{const sesion=JSON.parse(localStorage.getItem('sesion')||'{}'),headers={Authorization:`Bearer ${sesion.token||''}`};const r=await fetch('http://localhost:8080/api/clientes',{headers});const data=await r.json();if(!r.ok)throw Error(data.mensaje||'No se pudo cargar la lista.');clientes.value=data;await Promise.all(data.filter(c=>c.tieneFoto).map(async c=>{const img=await fetch(`http://localhost:8080/api/clientes/${c.id}/foto`,{headers});if(img.ok)fotoUrls.value[c.id]=URL.createObjectURL(await img.blob())}))}catch(e){mensaje.value=e.message;error.value=true}finally{cargando.value=false}})
onBeforeUnmount(()=>Object.values(fotoUrls.value).forEach(URL.revokeObjectURL))
</script>
<template><main class="min-h-screen bg-zinc-100 px-4 py-8 text-zinc-900"><section class="mx-auto max-w-6xl border border-zinc-200 bg-white p-6 shadow-sm sm:p-8"><header class="mb-6 flex flex-wrap items-center justify-between gap-3"><div><p class="text-sm text-zinc-500">Taller mecanico</p><h1 class="mt-1 text-2xl font-semibold">Clientes registrados</h1></div><RouterLink to="/clientes/nuevo" class="bg-zinc-900 px-4 py-2.5 text-sm text-white">Registrar cliente</RouterLink></header><p v-if="mensaje" role="alert" :class="error?'bg-red-50 text-red-700':'bg-zinc-100'" class="mb-4 px-3 py-2 text-sm">{{mensaje}}</p><p v-else-if="cargando" class="py-8 text-sm text-zinc-500">Cargando clientes...</p><p v-else-if="!clientes.length" class="py-8 text-sm text-zinc-500">No hay clientes registrados.</p><div v-else><div class="mb-5 flex flex-wrap gap-3"><div v-for="c in clientes" :key="c.id" class="flex items-center gap-2"><img v-if="fotoUrls[c.id]" :src="fotoUrls[c.id]" :alt="c.nombreCompleto" class="h-12 w-12 rounded-full border border-zinc-200 object-cover"><span class="text-sm">{{c.nombreCompleto}}</span></div></div><div class="overflow-x-auto"><table class="w-full min-w-[900px] border-collapse text-left text-sm"><thead><tr class="border-b border-zinc-300 text-zinc-500"><th class="p-3">Nombre</th><th class="p-3">Telefono</th><th class="p-3">Email</th><th class="p-3">Municipio</th><th class="p-3">Taller</th><th class="p-3">Edad</th></tr></thead><tbody><tr v-for="c in clientes" :key="c.id" class="border-b border-zinc-100"><td class="p-3 font-medium">{{c.nombreCompleto}}</td><td class="p-3">{{c.telefonoPersonal}}</td><td class="p-3">{{c.emailPersonal}}</td><td class="p-3">{{c.municipio}}, {{c.estado}}</td><td class="p-3">{{c.tallerId}}</td><td class="p-3">{{c.edad}}</td></tr></tbody></table></div></div></section></main></template>
